  public @Nullable CoreTablePayload table() {
    return table;
  }

  public void showTable(CoreTablePayload table) {
    this.table = table;
  }

  public static CoreTablePayload buildTable(CoreBlockEntity core, int containerId) {
    Level level = core.getLevel();
    Multiblock multiblock = core.multiblock();
    ScanResult<BlockPos> scan = core.lastScan();
    List<CoreTablePayload.Row> rows = new ArrayList<>();
    long draw = 0;
    if (level != null && multiblock != null) {
      for (BlockPos pos : multiblock.planters()) {
        if (level.isLoaded(pos)
            && level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
          rows.add(row(pos, planter));
          draw += planter.lastDraw();
        }
      }
    }
    CoreTablePayload.Totals totals =
        new CoreTablePayload.Totals(
            scan.formed(),
            scan.partCount(),
            MPConfig.PART_CAP.get(),
            scan.problem(),
            Optional.ofNullable(scan.problemPos()),
            core.power() == null ? 0 : core.power().stored(),
            core.power() == null ? 0 : core.power().capacity(),
            draw,
            core.fertilizer() == null ? 0 : core.fertilizer().available(),
            core.outputs() == null ? 0 : core.outputs().fillPercent(),
            core.meStatus());
    return new CoreTablePayload(containerId, totals, rows);
  }

  private static CoreTablePayload.Row row(BlockPos pos, PlanterBlockEntity planter) {
    ItemStack seedIcon =
        planter.seeds().size() == 0 ? ItemStack.EMPTY : planter.seeds().seed(0).copyWithCount(1);
    return new CoreTablePayload.Row(
        pos,
        seedIcon,
        planter.seeds().size(),
        planter.growing(),
        upgradeStack(planter, PlanterBlockEntity.UPGRADE_1),
        upgradeStack(planter, PlanterBlockEntity.UPGRADE_2),
        planter.upgraded(),
        planter.status());
  }

  private static ItemStack upgradeStack(PlanterBlockEntity planter, int slot) {
    return planter
        .soilAndUpgrades()
        .getResource(slot)
        .toStack(planter.soilAndUpgrades().getAmountAsInt(slot));
  }

  // The request comes from the client, so every field is checked again here against the open menu
  // and the live structure.
  public static void handle(ServerPlayer player, CoreRequestPayload request) {
    switch (request.action()) {
      case OPEN -> request.planter().ifPresent(pos -> openPlanter(player, pos));
      case BACK_TO_CORE -> backToCore(player);
    }
  }

  private static void openPlanter(ServerPlayer player, BlockPos pos) {
    if (!(player.containerMenu instanceof CoreMenu menu)
        || menu.core == null
        || !menu.stillValid(player)) {
      return;
    }
    Multiblock multiblock = menu.core.multiblock();
    if (!menu.core.lastScan().formed()
        || multiblock == null
        || !multiblock.planters().contains(pos)) {
      return;
    }
    if (player.level().isLoaded(pos)
        && player.level().getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
      switchMenu(player, () -> PlanterMenu.open(player, planter, menu.corePos, true));
    }
  }

